const body = $json.body ?? $json;
const allowedTypes=['PROTOTYPE_POLLUTION_ATTEMPT','PAYLOAD_COMPLEXITY_EXCEEDED','INJECTION_PROBE_DETECTED','AUTH_BRUTE_FORCE_BURST','RATE_LIMIT_EXCEEDED'];
if (!body || typeof body!=='object' || Array.isArray(body) || body.servicio!=='convoca-backend' || !allowedTypes.includes(body.tipo)) throw new Error('Evento de seguridad invalido');
if (!['alta','critica','media','baja'].includes(body.severidad) || typeof body.ruta!=='string' || body.ruta.length>150 || /[?#\r\n]/.test(body.ruta) || !body.ruta.startsWith('/')) throw new Error('Severidad o ruta invalida');
if(typeof body.ip!=='string' || body.ip.length>80 || !/^[a-f0-9:.]+$|^desconocida$/i.test(body.ip)) throw new Error('Origen invalido');
if(!Number.isFinite(Date.parse(body.timestamp)) || Math.abs(Date.now()-Date.parse(body.timestamp))>600000) throw new Error('Timestamp ausente o fuera de ventana');

const tipo = String(body.tipo ?? 'SECURITY_ANOMALY').slice(0, 80);
const severidad = String(body.severidad ?? 'media').toLowerCase();
const ip = String(body.ip ?? 'desconocida').slice(0, 80);
const ruta = String(body.ruta ?? '/api').slice(0, 150);
const metodo = String(body.metodo ?? 'HTTP').slice(0, 16);
const detalle = String(body.detalle ?? 'Evento de seguridad detectado por middleware').slice(0, 1000);
const timestamp = String(body.timestamp ?? new Date().toISOString());
const servicio = String(body.servicio ?? 'convoca-backend');

const fingerprint = `${tipo}:${ip}:${ruta}`;
const store = $getWorkflowStaticData('global');
store.incidents = store.incidents ?? {};
const prev = store.incidents[fingerprint];

const now=Date.now();
for(const [k,v] of Object.entries(store.incidents)) if(now-Date.parse(v.createdAt)>900000) delete store.incidents[k];
if(Object.keys(store.incidents).length>=1000) delete store.incidents[Object.keys(store.incidents)[0]];
if (prev?.issueId && now-Date.parse(prev.createdAt)<900000) {
  return {
    json: {
      duplicate: true,
      retryNotice: Boolean(prev.avisoPendiente && prev.correo),
      issueId: prev.issueId,
      tipo,
      severidad,
      ip,
      ruta,
      fingerprint
    }
  };
}

const esAlta = severidad === 'alta' || severidad === 'critica';
const summary = `[INC-SEC] ${tipo} desde ${ip} (${metodo} ${ruta})`.slice(0, 200);
const description = [
  'Incidencia de seguridad generada automáticamente por el flujo de respuesta ante incidentes (Actividad 14).',
  `Servicio: ${servicio}`,
  `Tipo de evento: ${tipo}`,
  `Severidad detectada: ${severidad}`,
  `IP origen: ${ip}`,
  `Petición: ${metodo} ${ruta}`,
  `Timestamp: ${timestamp}`,
  `Detalle: ${detalle}`,
  '',
  `[SEC_FINGERPRINT:${fingerprint}]`
].join('\n');

const issue = {
  summary,
  description,
  project: { id: 1, name: 'Convoca - A11 reproducible' },
  category: { name: 'Seguridad' },
  priority: esAlta ? { id: 40, name: 'high' } : { id: 30, name: 'normal' },
  severity: esAlta ? { id: 60, name: 'major' } : { id: 50, name: 'minor' },
  reproducibility: { id: 10, name: 'always' },
  handler: { name: 'juan-carrizo' },
  view_state: { id: 50, name: 'private' }
};

return {
  json: {
    duplicate: false,
    tipo,
    severidad,
    ip,
    metodo,
    ruta,
    detalle,
    timestamp,
    fingerprint,
    issue
  }
};

const origen = $('Normalizar y deduplicar incidente').item.json;
const issue = $json.issue ?? $json.issues?.[0] ?? $json;
const issueId = issue.id ?? $json.id;
if (!issueId) {
  throw new Error('Mantis no devolvió el ID de la incidencia de seguridad.');
}
const store = $getWorkflowStaticData('global');
store.incidents = store.incidents ?? {};
store.incidents[origen.fingerprint] = {
  issueId,
  createdAt: new Date().toISOString()
};

const emailBody = [
  '🚨 ALERTA DE SEGURIDAD — CONVOCA BACKEND (ACT. 14)',
  '--------------------------------------------------',
  `Ticket Mantis: #${issueId} (Categoría: Seguridad)`,
  `Tipo: ${origen.tipo}`,
  `Severidad: ${origen.severidad.toUpperCase()}`,
  `IP Origen: ${origen.ip}`,
  `Endpoint: ${origen.metodo} ${origen.ruta}`,
  `Fecha/Hora: ${origen.timestamp}`,
  `Detalle: ${origen.detalle}`,
  '',
  'Revisar evidencia en http://localhost:8989/view.php?id=' + issueId
].join('\n');

store.incidents[origen.fingerprint].avisoPendiente=true;
store.incidents[origen.fingerprint].correo={...origen,issueId,emailBody};
return {
  json: {
    ...origen,
    issueId,
    emailBody
  }
};
